en:
//　何故なら<RUBY text='・・'>剣と</RUBY>{Fade('絵演刀壱', 1000, 1000, null, true);}<RUBY text='・'>剣</RUBY>の{Fade('絵演刀弐', 1000, 500, null, true);}勝負になる。
